import re

def parse_duration(s: str) -> int:
    if not s.strip():
        raise ValueError("Input string cannot be empty or whitespace only")

    # Regex to match one or more groups of digits followed by a valid time unit
    # Must match the entire string (fullmatch) to ensure no invalid characters remain
    pattern = r'^(\d+[hms])+$'

    if not re.fullmatch(pattern, s):
        raise ValueError(f"Invalid duration format: {s}")

    total_seconds = 0
    # Find all digit-unit combinations
    for match in re.finditer(r'(\d+)([hms])', s):
        value = int(match.group(1))
        unit = match.group(2)

        if unit == 'h':
            total_seconds += value * 3600
        elif unit == 'm':
            total_seconds += value * 60
        elif unit == 's':
            total_seconds += value

    return total_seconds
