def allocate(total_cents: int, weights: list[int]) -> list[int]:
    if total_cents < 0:
        raise ValueError("total_cents must be non-negative")
    if not weights:
        raise ValueError("weights cannot be empty")
    if any(w < 0 for w in weights):
        raise ValueError("weights cannot contain negative values")
    total_weight = sum(weights)
    if total_weight == 0:
        raise ValueError("all weights cannot be zero")

    result = [0] * len(weights)

    # Base allocation rounded down
    for i, w in enumerate(weights):
        result[i] = (w * total_cents) // total_weight

    # Distribute remaining cents to parts with largest fractional remainder
    remainder = total_cents - sum(result)

    if remainder > 0:
        # Sort indices by fractional remainder descending, then by index ascending (earliest first for ties)
        sorted_indices = sorted(
            range(len(weights)), 
            key=lambda i: (-(weights[i] * total_cents) % total_weight, i)
        )

        # Distribute remaining cents in order of priority
        for i in range(remainder):
            if sorted_indices[i] is not None:  # Should always be valid given remainder < len(weights) usually, but logic holds generally
                idx = sorted_indices[i]
                result[idx] += 1

    return result
