import heapq

def build_order(deps: dict[str, list[str]]) -> list[str]:
    if not deps:
        return []

    in_degree = {item: 0 for item in deps}
    graph = {}
    all_nodes = set()

    # Build the graph and calculate in-degrees
    for item, dependencies in deps.items():
        in_degree[item] = len(dependencies)
        all_nodes.add(item)
        for dep in dependencies:
            if dep not in in_degree:
                in_degree[dep] = 0
            all_nodes.add(dep)

            # Edge from dependency to item (dependency must precede item)
            if dep not in graph:
                graph[dep] = []
            if item not in graph[dep]:
                graph[dep].append(item)

    # Initialize the heap with nodes having no dependencies
    ready = [node for node in all_nodes if in_degree[node] == 0]
    heapq.heapify(ready)

    result = []

    while ready:
        current = heapq.heappop(ready)
        result.append(current)

        if current in graph:
            for dependent in graph[current]:
                in_degree[dependent] -= 1
                if in_degree[dependent] == 0:
                    heapq.heappush(ready, dependent)

    # If the result length does not match the total nodes, there is a cycle
    if len(result) != len(all_nodes):
        raise ValueError("Cycle detected")

    return result
