import unicodedata

def sort_names(names: list[str]) -> list[str]:
    def clean_name(name: str) -> str:
        # Normalize to decomposed form (e.g., 'á' -> 'a' + combining acute accent)
        nfd = unicodedata.normalize('NFD', name)
        # Remove combining marks (accents)
        stripped = ''.join(c for c in nfd if unicodedata.category(c) != 'Mn')
        return stripped.lower()

    def key(name: str):
        clean = clean_name(name)
        # Rule 2: one without accents comes first. 
        # Compare lowercased original vs cleaned (lowercased). If equal, it had no accents.
        # We want "no accent" to sort lower (0) than "has accent" (1).
        has_accents = clean != name.lower()

        return (clean, has_accents, name)

    return sorted(names, key=key)
