                    current_line = chunk
                else:
                    # Check if chunk fits on current line with a space
                    if len(current_line) + 1 + len(chunk) <= width:
                        current_line += " " + chunk
                    else:
                        # Move current line to list and start new line with chunk
                        lines.append(current_line)
                        current_line = chunk

                i += width

            # If there's a remainder (should not happen with loop logic but for safety if logic changed)
            # actually the while loop handles all chars exactly. 
