import copy

def deep_merge(base: dict, override: dict) -> dict:
    # Start with a new dictionary structure. 
    # We need to ensure we don't share nested mutable objects with inputs.
    # Iterating through the union of keys is necessary.

    result = {}

    # Collect all unique keys
    all_keys = set(base.keys()) | set(override.keys())

    for key in all_keys:
        base_val = base.get(key)
        override_val = override.get(key)

        if key in override:
            if override_val is None:
                # Override value of None deletes the key
                pass
            elif base_val is not None and isinstance(base_val, dict) and isinstance(override_val, dict):
                # Both are dicts, merge recursively
                result[key] = deep_merge(base_val, override_val)
            else:
                # Replace (lists and other values are replaced)
                # Also ensure we don't share the list/dict with override input
                if isinstance(override_val, dict):
                    result[key] = copy.deepcopy(override_val)
                elif isinstance(override_val, list):
                    result[key] = copy.deepcopy(override_val)
                else:
                    # Scalars (int, str, None is handled above)
                    result[key] = override_val
        else:
            # Key only in base
            if isinstance(base_val, dict):
                result[key] = copy.deepcopy(base_val)
            elif isinstance(base_val, list):
                result[key] = copy.deepcopy(base_val)
            else:
                result[key] = base_val

    return result
