def latest_by_key(records: List[Dict[str, Any]], key: str) -> List[Dict[str, Any]]:
    def parse_dt(s: str) -> datetime.datetime:
        return datetime.datetime.fromisoformat(s.replace('Z', '+00:00'))

    best_records = {}

    for i, record in enumerate(records):
        k = record.get(key)
        updated_at = parse_dt(record['updated_at']) if 'updated_at' in record else None

        if k not in best_records:
            # First appearance of this key
            best_records[k] = {'record': record, 'index': i, 'time': updated_at}
        else:
            prev = best_records[k]

            # Check if current is better: later time OR same time but later index
            if updated_at > prev['time'] or (updated_at == prev['time'] and i > prev['index']):
                best_records[k]['record'] = record
                best_records[k]['index'] = i
                best_records[k]['time'] = updated_at

    return [best_records[k]['record'] for k in best_records]
