import heapq

def build_order(deps: dict[str, list[str]]) -> list[str]:
    all_nodes = set()
    for item, dependency_list in deps.items():
        all_nodes.add(item)
        for dep in dependency_list:
            all_nodes.add(dep)

    if not all_nodes:
        return []

    # Map node to number of unsatisfied dependencies (in-degree)
    in_degree = {node: 0 for node in all_nodes}
    # Map a node to the list of nodes that depend on it
    graph = {node: [] for node in all_nodes}

    for item, dependency_list in deps.items():
        unique_deps = set(dependency_list)
        # If 'item' depends on a dep, 'dep' must come before 'item'.
        # This is an edge from dep to item.
        # So 'item' has an in-degree increment for each unique dep.
        in_degree[item] = len(unique_deps)
        for dep in unique_deps:
            graph[dep].append(item)

    min_heap = []
    for node in all_nodes:
        if in_degree[node] == 0:
            heapq.heappush(min_heap, node)

    result = []
    while min_heap:
        current_node = heapq.heappop(min_heap)
        result.append(current_node)

        for neighbor in graph[current_node]:
            in_degree[neighbor] -= 1
            if in_degree[neighbor] == 0:
                heapq.heappush(min_heap, neighbor)

    if len(result) != len(all_nodes):
        raise ValueError("Cycle detected")

    return result
